#!/usr/bin/env python3
"""Cheap CE14 source closure check; no compiler, network or runtime access.

Conservatively scan all quoted includes (including conditional branches).
System headers and linker/ABI correctness remain compiler responsibilities.
"""
import argparse
from pathlib import Path
import re


MAKEFILES = ("server/Makefile.am", "server/gc/Makefile.am", "fuse/Makefile.am")
# Generated by configure/Vala/searpc, or supplied by the pinned CE toolchain.
GENERATED_OR_EXTERNAL = {
    "config.h", "seafile-config.h", "seafile-object.h",
    "searpc.h", "searpc-client.h", "searpc-server.h", "searpc-utils.h",
    "searpc-marshal.h", "searpc-signature.h", "evhtp.h",
}
TOKEN = re.compile(r"(?<![\w$({])(?:[\w.-]+/)*[\w.-]+\.[ch]\b")
INCLUDE = re.compile(r'^\s*#\s*include\s*"([^"]+)"', re.M)
# CE14 retains these dormant client/optional-backend includes. None is enabled
# by the Linux server recipe. Keep exceptions scoped to the exact includer.
INACTIVE_NATIVE_INCLUDES = {
    ("common/fs-mgr.c", "../daemon/vc-utils.h"),
    ("common/rpc-service.c", "../daemon/vc-utils.h"),
    ("common/cdc/cdc.h", "md5.h"),
    ("common/obj-backend-riak.c", "riak-client.h"),
}


def legacy(name):
    base = Path(name).name
    return (base.startswith(("cf-", "cloudfile-", "storage-backend-multi"))
            and not base.startswith("cf-v2-"))


def check(root):
    root = Path(root).resolve()
    errors = set()
    pending = []
    for name in MAKEFILES:
        makefile = root / name
        if not makefile.is_file():
            errors.add(f"missing build manifest: {name}")
            continue
        source = re.sub(r"(?m)#.*$", "", makefile.read_text())
        for token in TOKEN.findall(source):
            path = (makefile.parent / token).resolve()
            if not path.is_relative_to(root):
                errors.add(f"{name}: source escapes assembly: {token}")
            elif legacy(token):
                errors.add(f"{name}: legacy build input: {token}")
            elif not path.is_file():
                errors.add(f"{name}: missing build input: {token}")
            else:
                pending.append(path)
    seen = set()
    include_dirs = [root / p for p in
                    ("include", "lib", "common", "server", "server/gc", "fuse")]
    while pending:
        path = pending.pop()
        if path in seen:
            continue
        seen.add(path)
        # Ignore commented-out includes, but inspect all preprocessor branches.
        source = re.sub(r"/\*.*?\*/|//[^\n]*", "", path.read_text(), flags=re.S)
        for name in INCLUDE.findall(source):
            label = path.relative_to(root).as_posix()
            if (label, name) in INACTIVE_NATIVE_INCLUDES:
                continue
            if legacy(name):
                errors.add(f"{label}: legacy header: {name}")
                continue
            if name in GENERATED_OR_EXTERNAL:
                continue
            candidates = [(directory / name).resolve()
                          for directory in [path.parent, *include_dirs]]
            matches = [p for p in candidates if p.is_relative_to(root) and p.is_file()]
            if not matches:
                errors.add(f"{label}: unresolved quoted header: {name}")
            else:
                # Several native targets have their own seafile-session.h.
                # Scan all candidates to avoid hiding target-specific gaps.
                pending.extend(matches)
    return sorted(errors)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("server", type=Path, help="assembled seafile-server directory")
    args = parser.parse_args()
    errors = check(args.server)
    if errors:
        raise SystemExit("Native source preflight failed:\n" + "\n".join(errors))
    print("Native source dependency preflight passed (not a compilation result)")


if __name__ == "__main__":
    main()
